static const float AML_RBF_INTERCEPT[AML_NUM_CLASSES] = { -0.945097148f, -0.823897123f, -0.194826156f, -0.76101476f, -0.842755616f, -3.09962106f, -0.651522636f, -0.954753041f, -0.797357082f, -2.66697025f };


// =============================
// 推理:标准化 + RBF 打分(One-vs-Rest)
// =============================

static inline float aml_rbf_kernel(const float x[AML_FEATURES], float x_norm2, int sv_index) {
  // dist2 = ||x||^2 + ||sv||^2 - 2*dot(x,sv)
  float dot = 0.0f;
  for (int j = 0; j < AML_FEATURES; ++j) dot += x[j] * AML_RBF_SV[sv_index][j];
  float dist2 = x_norm2 + AML_RBF_SV_NORM2[sv_index] - 2.0f * dot;
  if (dist2 < 0.0f) dist2 = 0.0f;
  return expf(-AML_RBF_GAMMA * dist2);
}

static inline int aml_predict_class(const float x_in[AML_FEATURES]) {
  float x[AML_FEATURES];
  // Copy input
  for (int j = 0; j < AML_FEATURES; ++j) {
    x[j] = x_in[j];
  }

  // Robust scale (RobustScaler)
  for (int j = 0; j < AML_FEATURES; ++j) {
    x[j] = (x[j] - AML_SCALER_MEAN[j]) / AML_SCALER_SCALE[j];
  }

  // Feature weighting (must match training)
  // tof_gated (x[10]) *= 2
  x[10] *= 2.0f;

  float x_norm2 = 0.0f;
  for (int j = 0; j < AML_FEATURES; ++j) x_norm2 += x[j] * x[j];

  int best_k = 0;
  float best_score = -1e30f;
  for (int k = 0; k < AML_NUM_CLASSES; ++k) {
    float s = AML_RBF_INTERCEPT[k];
    int start = AML_RBF_SV_OFFSET[k];
    int end   = AML_RBF_SV_OFFSET[k + 1];
    for (int i = start; i < end; ++i) {
      s += AML_RBF_COEF[i] * aml_rbf_kernel(x, x_norm2, i);
    }
    if (s > best_score) { best_score = s; best_k = k; }
  }
  return best_k;
}

static inline const char* aml_predict_label(const float x_in[AML_FEATURES]) {
  return AML_CLASS_NAMES[ aml_predict_class(x_in) ];
}

